class Breaker:
    def __init__(self, fail_threshold=20, window=100, sleep_s=10):
        self.fail_threshold = fail_threshold  # trip if 20 fails in last 100 calls
        self.window = window
        self.sleep_s = sleep_s
        self.state = "CLOSED"
        self.recent = []  # ring buffer of 0/1
        self.opened_at = 0

    def allow(self, now):
        if self.state == "CLOSED":
            return True
        if self.state == "OPEN" and now - self.opened_at >= self.sleep_s:
            self.state = "HALF_OPEN"  # admit exactly one probe
            return True
        return False  # fast-fail to fallback, no thread blocked

    def record(self, ok, now):
        self.recent.append(0 if ok else 1)
        self.recent = self.recent[-self.window:]
        if self.state == "HALF_OPEN":
            self.state = "CLOSED" if ok else "OPEN"
            self.opened_at = now
        elif sum(self.recent) >= self.fail_threshold:
            self.state = "OPEN"  # isolate before retry storm builds
            self.opened_at = now

import random, time

def call_with_retry(fn, idempotency_key, max_attempts=4, base_ms=100):
    # Idempotency key lets the server dedupe redeliveries.
    # Without it, retry turns an omission fault into a double-charge.
    for attempt in range(max_attempts):
        try:
            return fn(idempotency_key=idempotency_key, timeout_ms=500)
        except TransientError:
            if attempt == max_attempts - 1:
                raise  # stop: fall back or shed, do not loop forever
            backoff = base_ms * (2 ** attempt)
            jitter = random.uniform(0, backoff)  # decorrelates herd
            time.sleep((backoff + jitter) / 1000.0)
        except PermanentError:
            raise  # never retry 4xx-style errors: pure waste + load
